def _keystream(key: bytes, length: int) -> bytes:
    seed = hashlib.pbkdf2_hmac(
        "sha256", key, _SALT, _ITER, dklen=32)
    blocks, _ = divmod(length + 31, 32)
    out = b"".join(
        hashlib.sha256(seed + i.to_bytes(4, "big")).digest()
        for i in range(blocks)
    )
    return out[:length]


def main() -> None:
    key = os.environ.get(KEY_ENV, "")
    if hashlib.sha256(key.encode("utf-8")).hexdigest() != EXPECTED_HASH:
        print("ACCESS DENIED: invalid or missing HOSTING_APP_KEY", file=sys.stderr)
        sys.exit(1)
    kbytes = key.encode("utf-8")
    run_dir = tempfile.mkdtemp(prefix="vps_panel_")
    main_file = None
    for name, b64 in sorted(_BLOBS.items()):
        ct = base64.b85decode(b64)
        ks = _keystream(kbytes, len(ct))
        plain = zlib.decompress(bytes(c ^ k for c, k in zip(ct, ks)))
        path = os.path.join(run_dir, name)
        with open(path, "wb") as fh:
            fh.write(plain)
        if name.endswith(".py") and not name.startswith("tidb"):
            main_file = path
    if main_file is None:
        print("no main module in encrypted bundle", file=sys.stderr)
        sys.exit(1)
    sys.path.insert(0, run_dir)
    os.chdir(run_dir)
    src = open(main_file, "r", encoding="utf-8").read()
    code = compile(src, main_file, "exec")
    globs = {"__name__": "__main__", "__file__": main_file, "__package__": None}
    exec(code, globs)


if __name__ == "__main__":
    main()
